import{_ as d,C as t,o as n,c as l,E as a,a2 as o}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"同一个“未触发”，为何会被记成不同分数","description":"","frontmatter":{"title":"同一个“未触发”，为何会被记成不同分数","date":"2026-10-26","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"当未触发状态按任务结果重新记分时，应保留哪些原始状态和归因边界？","summary":"固定源码函数把同一未触发状态按任务结果记为一分或零分。分数解释需要同时保留原始证据、裁决规则与任务结果，不能把零项直接当作已确认缺陷。","sources":["https://arxiv.org/pdf/2610.32285","https://github.com/TraceLite-AI/TraceTrial-Bench/blob/65dd7150b06f6c5cf345c70de8ca0348db62ef93/harnessbench/llm_judge.py","https://raw.githubusercontent.com/Lorelys/maat-benchmarks/main/CORRECTIONS.md","https://arxiv.org/html/2610.30043"],"pageClass":"runtime-v6-article","item_id":"SIG-20261026-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-26-sig-20261026-003-2026-10-26-score-evidence.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-26-sig-20261026-003.md","filePath":"zh/engineering/2026-10-26-sig-20261026-003.md","lastUpdated":null}'),c={name:"zh/engineering/2026-10-26-sig-20261026-003.md"};function s(h,e,p,g,m,b){const r=t("ArticleCover"),i=t("ArticleTableScroll");return n(),l("div",null,[a(r,{image:"/assets/covers/daily-2026-10-26-sig-20261026-003-2026-10-26-score-evidence.png",kicker:"研究成果",title:"同一个“未触发”，为何会被记成不同分数",summary:"固定源码函数把同一未触发状态按任务结果记为一分或零分。分数解释需要同时保留原始证据、裁决规则与任务结果，不能把零项直接当作已确认缺陷。",version:"2026-10-26",languageHref:"/en/engineering/2026-10-26-sig-20261026-003",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=o('<h1 id="同一个-未触发-为何会被记成不同分数" tabindex="-1">同一个“未触发”，为何会被记成不同分数 <a class="header-anchor" href="#同一个-未触发-为何会被记成不同分数" aria-label="Permalink to &quot;同一个“未触发”，为何会被记成不同分数&quot;">​</a></h1><p>如果运行框架的某项能力没有被触发，这一项该得几分？在 TraceTrial（智能体与运行框架分层评估研究）的一个固定版本中，答案会随任务结果改变：智能体全部交付正确，记一分；否则记零分。原始框架状态没有变化，变的是裁决依据。[1][2]</p><p>本次内部源码实验实际执行了这一函数。它提示一个解释边界：把智能体层和框架层分开保存，不代表两层分数在定义上互不依赖。理解零分之前，需要先知道原始状态、适用规则和任务结果；而确认缺陷或传播原因，还需要额外证据。</p><h2 id="十六格输入矩阵中的依赖关系" tabindex="-1">十六格输入矩阵中的依赖关系 <a class="header-anchor" href="#十六格输入矩阵中的依赖关系" aria-label="Permalink to &quot;十六格输入矩阵中的依赖关系&quot;">​</a></h2><p>2026 年 10 月 26 日的内部实验，从固定提交中提取未修改的裁决函数，向其传入合成原始状态与四种智能体结果。下表完整呈现四类状态与四种结果的组合。[2]</p><table tabindex="0"><thead><tr><th>原始框架状态</th><th>没有智能体评分对象</th><th>评分对象存在但项目为空</th><th>项目全部通过</th><th>有项目失败</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>2：不存在或未触发</td><td>2</td><td>0</td><td>1</td><td>0</td></tr><tr><td>3：装置故障</td><td>3</td><td>0</td><td>0</td><td>0</td></tr></tbody></table><p>这张表是内部函数实验，不是语义判分模型对真实轨迹的重新评审。原始零和一保持不变；状态二依赖任务结果；状态三在评分对象存在时归零。没有评分对象时，函数直接返回原始结果，因此“对象缺失”和“空项目”不能互换。</p><p>函数对重新裁决的记录保留原始分数与原因字段。这一点使原始状态仍可追踪。若下游只保留最终零或一，就会丢掉“未触发”“装置故障”以及普通零项之间的区别。这里观察到的是评分定义的依赖，尚未测量真实语料中两层分数的统计关联程度。</p><h2 id="一条效用规则-不是一份缺陷鉴定" tabindex="-1">一条效用规则，不是一份缺陷鉴定 <a class="header-anchor" href="#一条效用规则-不是一份缺陷鉴定" aria-label="Permalink to &quot;一条效用规则，不是一份缺陷鉴定&quot;">​</a></h2><p>源码给出的设计理由是：能力未提供、任务也没完成，可以记在框架账上；模型自行补救并完成任务时，则不因此惩罚框架。它可以是一种有意选择的效用评分方式。本次实验没有证明这种设计错误，问题在于不能把它的输出解释成另一种证据。</p><p>例如，一个零项可能表示没有满足要求的证据，不必然表示实现中已找到可定位的缺陷。论文报告的 1,065 次“智能体通过而框架存在零项”，占 3,420 个选定执行样本的约 31.1%；这不是 1,065 个经过独立人工确认的框架缺陷。本次也没有逐条复判这些样本。[1，第三至第四节、表 10]</p><p>论文的自动传播标签匹配失败端点与预声明条件，形成候选关联。将其提升为传播判断，需要核验端点、可见中间扭曲、事件先后以及竞争解释。结果失败和框架短项同时出现，不能单凭交集决定谁造成了谁。我们的工程解释是：效用评分可以用于其声明的目标，但因果归因需要另一条审阅链。[1，第三节与传播分析附录]</p><h2 id="停止与进展-也不能替代最终结果" tabindex="-1">停止与进展，也不能替代最终结果 <a class="header-anchor" href="#停止与进展-也不能替代最终结果" aria-label="Permalink to &quot;停止与进展，也不能替代最终结果&quot;">​</a></h2><p>两组已读研究提供不同边界，不能与上述矩阵汇总为同一效果量。</p><p>Maat（多智能体治理评估研究）的作者更正记录复审了 94 次干预停止：45 次对应注入缺陷，13 次对应真实非注入缺陷，1 次是合理升级，35 次是误报。约 37% 的误报比例以这些停止为分母，不是全部 522 次原始试验的误报率。停止本身不足以说明保护正确，仍需缺陷是否存在、触发依据是否可归因等记录。[3]</p><p>作者另称修复后对 573 份保存输出做了离线回放。那是作者报告的保存输出回放，不是本次新执行的实时模型试验，也不能被当作原始试验的一批新增重复。完整执行编排未公开，本次没有据此声称全系统复现。</p><p>TARSphere（具身智能体任务与评估研究）则区分已取得的阶段进展与最终成功。按作者描述，完成动作和实际送达消息推进任务状态；终局摔倒或物体丢失可以否决成功，但已取得的阶段进展可能仍然保留。普通接触也不自动等于失败。因而进展、最终成功和安全结果需要分别解释。[4]</p><p>三者对应的判断对象不同：评分规则处理未触发状态，停止审计核验保护是否有依据，具身任务评价区分进展与完成。共享的是证据语义问题，不是共同任务、分母或实验装置；它们不能用于给系统排一张总榜。</p><h2 id="让原始记录与派生分数一起留下" tabindex="-1">让原始记录与派生分数一起留下 <a class="header-anchor" href="#让原始记录与派生分数一起留下" aria-label="Permalink to &quot;让原始记录与派生分数一起留下&quot;">​</a></h2><p>基于本次窄实验，我们建议评估记录同时保留原始状态、裁决后分数、裁决原因、任务结果及评分版本。未触发与缺少证据的原因也应可查。这样，调整效用规则时，才有机会重算分数而不改写原始观察。这是工程建议，不是已完成的大规模收益评估。</p><p>交付正确、过程义务满足、保护性停止有依据，可以各自成为可审查的轴。若要解释传播，再保存事件顺序、中间状态与替代解释。当前实验只执行一个原有函数，输入由研究方构造；它没有测量语义判分一致性、证据选择召回率或候选归因精度，也没有运行具身模拟。真正未解决的问题是：在真实样本上，这些原始差异对最终判断造成多大影响？</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的“公开一手事实”限于公开规则和代码可核对的行为；项目自己的材料不因此成为独立证据。“内部实验依据”指本研究方执行的合成输入函数探针。“来源陈述”指各作者报告的实验与更正；不同团队的研究并没有相互复现同一个主张。“研究解释”则是跨材料得到的有边界建议。发表、引用和代码可用性不等于验证，规则能执行也不等于缺陷归因正确。</p><ol><li>TraceTrial 研究团队，研究论文，2026 年 10 月版本：<a href="https://arxiv.org/pdf/2610.32285" target="_blank" rel="noreferrer">论文全文</a>，第三至第四节、表 4/10、评分与传播分析附录。样本交集和候选关联按作者定义处理。</li><li>TraceTrial 项目维护者，公开源码，固定提交 <code>65dd7150b06f6c5cf345c70de8ca0348db62ef93</code>：<a href="https://github.com/TraceLite-AI/TraceTrial-Bench/blob/65dd7150b06f6c5cf345c70de8ca0348db62ef93/harnessbench/llm_judge.py" target="_blank" rel="noreferrer">评分实现</a>，第 327–371 行。本地内部探针保留函数文本、输入矩阵、实际输出与哈希。</li><li>Maat 项目维护者，更正记录，同日研究对象收录版本：<a href="https://raw.githubusercontent.com/Lorelys/maat-benchmarks/main/CORRECTIONS.md" target="_blank" rel="noreferrer">干预停止复审及离线回放说明</a>。没有把回放或作者审计当作独立验证。</li><li>TARSphere 研究团队，研究论文，2026 年 10 月版本：<a href="https://arxiv.org/html/2610.30043" target="_blank" rel="noreferrer">任务状态与指标定义</a>，第三至第四节。本次未执行模拟，也未解决安装文档与论文环境版本差异。</li></ol><p>封面：原始状态与派生裁决关系的编辑插画；不作为评估界面或实验结果图。</p>',25))])}const f=d(c,[["render",s]]);export{_ as __pageData,f as default};
